insert into products (slug, name, category, description, active) values ('hbelt-tg', 'H-Flex Belt™ – La ceinture sans boucle, confortable et ajustable', null, 'Découvrez la H-Flex Belt™, la ceinture révolutionnaire sans boucle qui vous offre confort et liberté totale. Fini la douleur au ventre, fini la boucle qui gêne : ◈ Confort absolu : fini la boucle qui rentre dans le ventre ◈ Ultra simple à utiliser : crochet + Velcro → prêt en 10 secondes ◈ Maintien parfait : votre pantalon reste en place toute la journée ◈ Unisexe & Taille Unique : s’adapte à toutes les morphologies', true) on conflict (slug) do update set name = excluded.name, category = excluded.category, description = excluded.description;
