insert into products (slug, name, category, description, active) values ('tomi-dynasty-t106', 'TOMI Dynasty ™ T106 – La montre qui attire les regards', null, 'L''élégance ne fait pas de bruit. Elle se remarque. Vous n''avez pas besoin d''une montre à plusieurs centaines d''euros pour avoir de l''allure. La TOMI Dynasty™ T106 combine un design moderne, un cadran ajouré fascinant et une finition haut de gamme qui donnent immédiatement une impression de prestige. ◈ Design premium ◈ Style minimaliste et moderne ◈ Détails inspirés de l''horlogerie de luxe ◈ Mouvement Quartz de haute précision', true) on conflict (slug) do update set name = excluded.name, category = excluded.category, description = excluded.description;
