insert into products (slug, name, category, description, active) values ('ceinture-aurion', 'AURION™ — La ceinture automatique en cuir véritable qui s''ajuste parfaitement à votre taille', null, 'Changez votre façon de porter une ceinture Une ceinture traditionnelle vous oblige à choisir entre plusieurs trous fixes. Trop serrée après un repas ? Trop lâche pendant la journée ? Ce problème appartient désormais au passé. ◈ Ajustement précis au millimètre près ◈ Design moderne et minimaliste ◈ Facile à mettre et à retirer ◈ Convient aux tenues professionnelles comme décontractées', true) on conflict (slug) do update set name = excluded.name, category = excluded.category, description = excluded.description;
