insert into products (slug, name, category, description, active) values ('vaultpop', 'VaultPop™ — Portefeuille Pop-Up RFID en cuir véritable', null, 'Ultra fin. Ultra pratique. Ultra sécurisé. Vous en avez assez des portefeuilles épais et désordonnés ? VaultPop™ combine un design moderne en aluminium, un accès instantané à vos cartes et une protection RFID pour garder vos données en sécurité au quotidien. ◈ Jusqu’à 15 cartes + billets ◈ Système pop‑up ◈ Protection RFID intégrée ◈ Design ultra fin', true) on conflict (slug) do update set name = excluded.name, category = excluded.category, description = excluded.description;
