insert into products (slug, name, category, description, active) values ('cotonpur', 'Pack de 3 Boxers CotonPur™ : Le Confort Naturel au Quotidien', null, 'Redécouvrez le Vrai Confort avec le Boxer CotonPur Vous en avez assez des sous-vêtements qui irritent, retiennent la chaleur et se déforment ? Passez au niveau supérieur avec les boxers CotonPur™. Conçus avec un coton de première qualité, ils offrent une douceur inégalée, une respirabilité optimale et une durabilité exceptionnelle. ◈ 🌿 100% Coton Respirant ◈ 🛡️ Anti-Irritations & Hypoallergénique ◈ 💪 Durabilité Exceptionnelle ◈ ✨ Coupe Parfaite & Discrétion', true) on conflict (slug) do update set name = excluded.name, category = excluded.category, description = excluded.description;
