insert into products (slug, name, category, description, active) values ('arctic-vector', 'Arctic Vector™ - L''Élégante Sacoche au Design Professionnel', null, 'Élevez Votre Quotidien avec Style et Fonctionnalité Découvrez l''Arctic Vector™, bien plus qu''une simple sacoche : c''est le compagnon idéal de l''homme moderne, conçu pour allier élégance avant-gardiste et performance inégalée. ◈ Protection Contre les Intempéries ◈ Design Minimaliste, Impact Maximal ◈ Organisation Intuitive et Optimisée ◈ Légèreté et Durabilité', true) on conflict (slug) do update set name = excluded.name, category = excluded.category, description = excluded.description;
