insert into products (slug, name, category, description, active) values ('born-pretty-kit', 'Born Pretty – Kit Polygel Professionnel pour Ongles avec Lampe UV/LED – Gel d''Extension 15 ml', null, 'Le kit pour ongles le plus complet pour faire ses ongles a la maison. Découvrez le Kit Polygel BORN PRETTY, une solution tout-en-un pour créer des ongles tendances, résistants et d’aspect professionnel à domicile ou en salon. Idéal pour les débutants comme pour les pro. ◈ Facile à utiliser – modèle le gel sans coulure ◈ Finition professionnelle – effet gel brillant ◈ Kit complet – tout ce dont vous avez besoin inclus ◈ Résultats longue tenue – jusqu’à plusieurs semaines', true) on conflict (slug) do update set name = excluded.name, category = excluded.category, description = excluded.description;
